import React, { useState, useEffect } from 'react';
import './App.css';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
} from 'recharts';
import {
  Wallet,
  ArrowUpCircle,
  ArrowDownCircle,
  PlusCircle,
  LayoutDashboard,
  History,
} from 'lucide-react';

const API_URL = 'http://localhost:5296/api/transactions';

function CustomTooltip({ active, payload, label }) {
  if (!active || !payload || !payload.length) return null;
  return (
    <div className="custom-tooltip">
      <div className="tt-title">{label}</div>
      <div className="tt-value">Monto: {Number(payload[0].value).toLocaleString()}</div>
    </div>
  );
}

export default function App() {
  const [transactions, setTransactions] = useState([]);
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState('Ingreso');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchTransactions();
  }, []);

  async function fetchTransactions() {
    try {
      const res = await fetch(API_URL);
      if (!res.ok) return;
      const data = await res.json();
      setTransactions(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error('API error', err);
    }
  }

  async function handleSubmit(e) {
    e.preventDefault();
    if (!description || !amount) return;
    const payload = { description, amount: parseFloat(amount), type, date: new Date().toISOString() };
    try {
      setLoading(true);
      const res = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (res.ok) {
        setDescription('');
        setAmount('');
        await fetchTransactions();
      }
    } catch (err) {
      console.error('Save error', err);
    } finally {
      setLoading(false);
    }
  }

  const ingresos = transactions
    .filter(t => t.type === 'Ingreso')
    .reduce((s, t) => s + (Number(t.amount) || 0), 0);

  const gastos = transactions
    .filter(t => t.type === 'Gasto')
    .reduce((s, t) => s + (Number(t.amount) || 0), 0);

  const balance = ingresos - gastos;

  const chartData = transactions.slice().reverse().map((t, i) => ({
    name: t.description || `Movimiento ${i + 1}`,
    Monto: Number(t.amount) || 0,
  }));

  return (
    <div className="app-container">
      <aside className="sidebar">
        <h2>Finanzas Pro</h2>
        <div className="menu-item active">
          <LayoutDashboard size={18} />
          <span>Dashboard</span>
        </div>
        <div className="menu-item">
          <History size={18} />
          <span>Historial</span>
        </div>
      </aside>

      <main className="main-content">
        <section className="metrics-grid">
          <div className="metric-card">
            <div className="metric-info">
              <span>Ingresos</span>
              <h3 style={{ color: 'var(--color-income)' }}>${ingresos.toFixed(2)}</h3>
            </div>
            <ArrowUpCircle color="#10b981" size={36} />
          </div>

          <div className="metric-card">
            <div className="metric-info">
              <span>Gastos</span>
              <h3 style={{ color: 'var(--color-expense)' }}>${gastos.toFixed(2)}</h3>
            </div>
            <ArrowDownCircle color="#ef4444" size={36} />
          </div>

          <div className="metric-card">
            <div className="metric-info">
              <span>Balance Total</span>
              <h3>${balance.toFixed(2)}</h3>
            </div>
            <Wallet color="#3b82f6" size={36} />
          </div>
        </section>

        <div className="dashboard-body">
          <div className="card-panel graphic-panel">
            <h3>Evolución Financiera (Últimos Movimientos)</h3>

            <div className="chart-wrapper">
              {chartData.length === 0 ? (
                <p className="muted">Agrega movimientos para generar analíticas.</p>
              ) : (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData} margin={{ top: 6, right: 6, left: 6, bottom: 6 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.03)" />
                    <XAxis dataKey="name" stroke="var(--text-muted)" />
                    <YAxis stroke="var(--text-muted)" />
                    <Tooltip content={<CustomTooltip />} wrapperStyle={{ zIndex: 1200 }} />
                    <Area type="monotone" dataKey="Monto" stroke="var(--accent-blue)" fill="var(--accent-blue)" fillOpacity={0.12} />
                  </AreaChart>
                </ResponsiveContainer>
              )}
            </div>

            <div className="recent-activity">
              <h3>Transactions / Recent Activity</h3>
              <div className="transaction-list">
                {transactions.map((t, i) => (
                  <div className="transaction-item" key={t.id ?? i}>
                    <div className="tx-info">
                      <h4>{t.description}</h4>
                      <span>{t.type}</span>
                    </div>
                    <div className={`tx-amount ${t.type === 'Ingreso' ? 'ingreso' : 'gasto'}`}>
                      {t.type === 'Ingreso' ? '+' : '-'} ${Number(t.amount).toFixed(2)}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="card-panel form-panel">
            <h3>
              <PlusCircle size={18} style={{ verticalAlign: 'middle', marginRight: 8 }} />
              Agregar Transacción
            </h3>

            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <label>Descripción</label>
                <input value={description} onChange={e => setDescription(e.target.value)} placeholder="Ej. Sueldo" />
              </div>

              <div className="form-group">
                <label>Monto</label>
                <input value={amount} onChange={e => setAmount(e.target.value)} type="number" step="0.01" placeholder="Monto" />
              </div>

              <div className="form-group">
                <label>Tipo de Transacción</label>
                <select value={type} onChange={e => setType(e.target.value)}>
                  <option value="Ingreso">Ingreso</option>
                  <option value="Gasto">Gasto</option>
                </select>
              </div>

              <button type="submit" className="btn-submit" disabled={loading}>
                {loading ? 'Guardando...' : 'Guardar'}
              </button>
            </form>
          </div>
        </div>
      </main>
    </div>
  );
}
